contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public {
        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.withdraw(value); if (__ESBMC_reverted()) return;

        assert(address(c).balance <= balBefore && c.depositsCount() == countBefore);
    }

    receive() external payable {}
}

